<script setup lang="ts">
import { computed,ref } from 'vue'
import { onPullDownRefresh,onShow } from '@dcloudio/uni-app'
import WareState from '@/shared/components/WareState.vue'
import { coldStorageApi } from '../../api/cold-storage.api'
import StoragePanel from '../../components/StoragePanel.vue'
import ColdImagePicker from '../../components/ColdImagePicker.vue'
import type { ColdStorageItem,ColdStorageMode,ColdStorageOverview } from '../../models/cold-storage'
import { sessionStore } from '@/store/session'
import SessionDatePicker from '@/shared/components/SessionDatePicker.vue'
import SessionTrigger from '@/shared/components/SessionTrigger.vue'

const overview=ref<ColdStorageOverview>({customerCount:0,bareCustomerCount:0,packageCustomerCount:0,packageTotal:0,todayOutTotalCount:0,todayOutFinishCount:0})
const mode=ref<ColdStorageMode>('pending'),keyword=ref(''),storeType=ref(0),storeRoundNo=ref(''),list=ref<ColdStorageItem[]>([]),loading=ref(false),error=ref(''),searchTimer=ref<ReturnType<typeof setTimeout>>()
const finishItem=ref<ColdStorageItem>(),finishImages=ref<string[]>([]),finishRemark=ref(''),finishBunchNum=ref(''),submitting=ref(false)
const roundVisible=ref(false),typeVisible=ref(false),draftType=ref(0)
const typeOptions=[{label:'全部类型',value:0},{label:'包裹暂存',value:1},{label:'裸花暂存',value:2}]
const filters=computed(()=>({keyword:keyword.value,storeType:storeType.value,storeRoundNo:storeRoundNo.value}))
async function load(){loading.value=true;error.value='';try{const [stats,items]=await Promise.all([coldStorageApi.overview(),mode.value==='current'?coldStorageApi.current(filters.value):coldStorageApi.outTasks(filters.value,mode.value==='done'?20:10)]);overview.value=stats;list.value=items}catch(e){error.value=e instanceof Error?e.message:'冷库数据加载失败'}finally{loading.value=false;uni.stopPullDownRefresh()}}
function changeMode(value:ColdStorageMode){if(mode.value===value)return;mode.value=value;load()}
function onSearch(){clearTimeout(searchTimer.value);searchTimer.value=setTimeout(load,300)}
function openRound(){roundVisible.value=true}
function confirmRound(){load()}
function openType(){draftType.value=storeType.value;typeVisible.value=true}
function confirmType(){storeType.value=draftType.value;typeVisible.value=false;load()}
function openRegister(){uni.navigateTo({url:`/features/cold-storage/pages/bare-register/index${storeRoundNo.value?`?date=${storeRoundNo.value}`:''}`})}
function openFinish(item:ColdStorageItem){finishItem.value=item;finishImages.value=[];finishRemark.value='';finishBunchNum.value=item.outType===3?String(item.outBunchNum):''}
function closeFinish(){if(!submitting.value)finishItem.value=undefined}
async function submitFinish(){const item=finishItem.value;if(!item)return;if(!finishImages.value.length)return uni.showToast({title:'请上传出库照片',icon:'none'});const bunch=item.outType===3?Number(finishBunchNum.value):undefined;if(item.outType===3&&(!Number.isInteger(bunch)||!bunch||bunch>item.outBunchNum))return uni.showToast({title:'最终扎数不能超过审批数量',icon:'none'});submitting.value=true;try{await coldStorageApi.finishOut(item.outTaskId,{finishBunchNum:bunch,imageUrls:finishImages.value,remark:finishRemark.value});uni.showToast({title:'出库完成',icon:'success'});finishItem.value=undefined;load()}catch(e){uni.showToast({title:e instanceof Error?e.message:'出库失败',icon:'none'})}finally{submitting.value=false}}
onShow(load);onPullDownRefresh(load)
</script>
<template><view class="page">
  <view class="page-head"><SessionTrigger :value="storeRoundNo" @click="openRound"/><view class="head-badge">冷库暂存</view></view>
  <view class="summary"><view><strong>{{overview.customerCount}}</strong><text>暂存客户</text></view><view><strong>{{overview.bareCustomerCount}}</strong><text>裸花客户</text></view><view><strong>{{overview.packageCustomerCount}}<small> / {{overview.packageTotal}}件</small></strong><text>包裹客户</text></view><view class="progress"><strong>{{overview.todayOutFinishCount}}/{{overview.todayOutTotalCount}}</strong><text>今日出库</text></view></view>
  <view class="action-row"><view class="search"><input v-model="keyword" placeholder="手机号 / 昵称 / 货位" @input="onSearch"/><text>⌕</text></view><button v-if="sessionStore.can('coldStorage.registerBare')" class="register-button" @click="openRegister">裸花暂存登记</button></view>
  <view class="filter"><view class="tabs"><text :class="{active:mode==='pending'}" @click="changeMode('pending')">待出库</text><text :class="{active:mode==='done'}" @click="changeMode('done')">已出库</text><text :class="{active:mode==='current'}" @click="changeMode('current')">暂存中</text></view><view class="compact-trigger" @click="openType"><text>{{typeOptions.find(item=>item.value===storeType)?.label}}</text><i class="selector-down"/></view></view>
  <WareState v-if="loading" type="loading" title="正在加载冷库暂存"/><WareState v-else-if="error" type="error" title="加载失败" :description="error" action-label="重新加载" @action="load"/><view v-else-if="list.length" class="list"><StoragePanel v-for="item in list" :key="`${mode}-${item.outTaskId||item.coldStockId}`" :item="item" :mode="mode" :allow-finish="sessionStore.can('coldStorage.finishOut')" @finish="openFinish"/></view><WareState v-else type="empty" title="暂无冷库暂存数据" description="当前筛选条件下没有对应记录"/>
  <view v-if="finishItem" class="mask" @click="closeFinish"><view class="drawer" @click.stop><view class="handle"/><view class="drawer-head"><view><strong>确认出库</strong><text>{{finishItem.purchaserNick}} · {{finishItem.locationNo}}</text></view><text @click="closeFinish">×</text></view><view v-if="finishItem.outType===3" class="field"><text>最终出库扎数 <i>必填</i></text><view class="number"><input v-model="finishBunchNum" type="number"/><strong>扎</strong></view><small>客服审批 {{finishItem.outBunchNum}} 扎，不可超过审批数量</small></view><view class="field"><text>出库照片 <i>必填</i></text><ColdImagePicker v-model="finishImages"/></view><view class="field"><text>出库备注</text><textarea v-model="finishRemark" maxlength="500" placeholder="可填写出库说明"/></view><button class="submit" :disabled="submitting" @click="submitFinish">{{submitting?'提交中…':'确认出库'}}</button></view></view>
  <SessionDatePicker v-model="storeRoundNo" v-model:visible="roundVisible" allow-all title="选择场次" @confirm="confirmRound"/>
  <view v-if="typeVisible" class="selector-mask" @click="typeVisible=false"><view class="selector-drawer" @click.stop><view class="selector-head"><strong>选择暂存类型</strong><text @click="confirmType">确定</text></view><view class="selector-grid"><view v-for="item in typeOptions" :key="item.value" :class="{active:draftType===item.value}" @click="draftType=item.value">{{item.label}}</view></view></view></view>
</view></template>
<style scoped lang="scss">
.page{min-height:100vh;padding:24rpx}.summary{display:grid;grid-template-columns:repeat(4,1fr);padding:24rpx 8rpx;border-radius:22rpx;background:#fff;box-shadow:var(--wms-shadow-card)}.summary view{display:flex;align-items:center;flex-direction:column;border-right:1rpx solid var(--wms-border)}.summary view:last-child{border:0}.summary strong{font-size:30rpx}.summary small{font-size:16rpx}.summary text{margin-top:7rpx;color:var(--wms-text-secondary);font-size:17rpx}.summary .progress strong{color:var(--wms-warning)}.head{display:flex;align-items:center;justify-content:space-between;margin:28rpx 0 16rpx}.head strong{font-size:30rpx}.head button{height:62rpx;margin:0;padding:0 20rpx;border:0;border-radius:13rpx;background:var(--wms-primary-700);color:#fff;font-size:20rpx;line-height:62rpx}.search{display:flex;height:70rpx;align-items:center;padding:0 20rpx;border-radius:15rpx;background:#fff}.search input{flex:1;font-size:22rpx}.search text{color:var(--wms-primary-700);font-size:30rpx}.filter{display:flex;height:80rpx;align-items:center;gap:10rpx}.tabs{display:flex;height:80rpx;min-width:0;flex:1;align-items:center;gap:24rpx;border-bottom:1rpx solid var(--wms-border)}.tabs text{position:relative;flex:none;color:var(--wms-text-secondary);font-size:21rpx}.tabs .active{color:var(--wms-primary-700);font-weight:750}.tabs .active:after{position:absolute;right:0;bottom:-27rpx;left:0;height:4rpx;border-radius:4rpx;background:var(--wms-primary-700);content:''}.compact-trigger{display:flex;max-width:150rpx;height:54rpx;align-items:center;gap:8rpx;padding:0 9rpx;border-radius:12rpx;background:#fff;color:var(--wms-primary-700);font-size:17rpx}.compact-trigger>text{overflow:hidden;white-space:nowrap;text-overflow:ellipsis}.selector-down{width:9rpx;height:9rpx;flex:none;border-right:2rpx solid currentColor;border-bottom:2rpx solid currentColor;transform:rotate(45deg) translateY(-3rpx)}.list{display:flex;flex-direction:column;gap:15rpx}.mask,.selector-mask{position:fixed;z-index:50;inset:0;display:flex;align-items:flex-end;background:rgba(23,43,41,.45)}.selector-mask{z-index:60}.drawer{box-sizing:border-box;width:100%;max-height:90vh;padding:14rpx 28rpx calc(28rpx + env(safe-area-inset-bottom));overflow:auto;border-radius:30rpx 30rpx 0 0;background:#fff}.handle{width:70rpx;height:7rpx;margin:0 auto 22rpx;border-radius:7rpx;background:var(--wms-border)}.drawer-head{display:flex;justify-content:space-between}.drawer-head strong,.drawer-head text{display:block}.drawer-head strong{font-size:30rpx}.drawer-head view>text{margin-top:7rpx;color:var(--wms-text-secondary);font-size:19rpx}.drawer-head>text{font-size:35rpx}.selector-drawer{box-sizing:border-box;width:100%;padding:25rpx 24rpx calc(30rpx + env(safe-area-inset-bottom));border-radius:28rpx 28rpx 0 0;background:#fff}.selector-head{display:flex;align-items:center;justify-content:space-between}.selector-head strong{font-size:29rpx}.selector-head text{color:var(--wms-primary-700);font-size:23rpx}.selector-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14rpx;margin-top:22rpx}.selector-grid view{height:70rpx;border:2rpx solid transparent;border-radius:10rpx;background:#f0f2f2;font-size:22rpx;line-height:70rpx;text-align:center}.selector-grid .active{border-color:var(--wms-primary-700);background:var(--wms-surface-soft);color:var(--wms-primary-700);font-weight:700}.field{margin-top:26rpx}.field>text{display:block;margin-bottom:13rpx;font-size:22rpx;font-weight:700}.field i{color:var(--wms-danger);font-size:17rpx;font-style:normal}.number{display:flex;height:70rpx;align-items:center;padding:0 18rpx;border-radius:13rpx;background:var(--wms-page)}.number input{flex:1}.number strong{font-size:21rpx}.field small{display:block;margin-top:9rpx;color:var(--wms-warning);font-size:17rpx}.field textarea{box-sizing:border-box;width:100%;height:130rpx;padding:17rpx;border-radius:13rpx;background:var(--wms-page);font-size:21rpx}.submit{height:82rpx;margin-top:28rpx;border:0;border-radius:16rpx;background:var(--wms-primary-700);color:#fff;font-size:24rpx;font-weight:700;line-height:82rpx}.submit[disabled]{background:#bdccc9}
</style>
<style scoped>.page-head{display:flex;align-items:center;justify-content:space-between;gap:20rpx;margin:4rpx 0 18rpx}.page-head :deep(.session-trigger){flex:none}.head-badge{padding:9rpx 15rpx;border-radius:999rpx;background:var(--wms-surface-soft);color:var(--wms-primary-700);font-size:22rpx;font-weight:700;white-space:nowrap}.action-row{display:flex;align-items:center;gap:14rpx;margin:22rpx 0 0}.action-row .search{min-width:0;flex:1}.register-button{box-sizing:border-box;height:70rpx;flex:none;margin:0;padding:0 18rpx;border:0;border-radius:15rpx;background:var(--wms-primary-700);color:#fff;font-size:20rpx;font-weight:700;line-height:70rpx;white-space:nowrap}.register-button:after{border:0}</style>
